mapper.select:
SELECT ts.station_order
FROM train_station ts
         JOIN station s ON s.id = ts.station_id
WHERE ts.train_id = #{trainId}
  AND s.station_name = #{stationName}

SELECT t.id AS train_id, t.train_no AS train_no, t.train_type AS train_type, t.direction AS direction, t.bureau AS bureau, fs.station_name AS from_station, ts.station_name AS to_station, tfs.departure_time AS departure_time, tts.arrival_time AS arrival_time, FLOOR((tts.day_offset * 1440 + TIME_TO_SEC(tts.arrival_time) / 60) - (tfs.day_offset * 1440 + TIME_TO_SEC(tfs.departure_time) / 60)) AS duration_minutes, (tts.mileage_from_start - tfs.mileage_from_start) AS mileage, (SELECT MIN(i.remaining_count) FROM seat_inventory i WHERE i.train_id = t.id AND i.travel_date = #{travelDate} AND i.seat_type = #{seatType} AND i.from_station_order >= tfs.station_order AND i.to_station_order <= tts.station_order) AS remaining_count, (SELECT SUM(i.price) FROM seat_inventory i WHERE i.train_id = t.id AND i.travel_date = #{travelDate} AND i.seat_type = #{seatType} AND i.from_station_order >= tfs.station_order AND i.to_station_order <= tts.station_order) AS total_price FROM train t JOIN train_station tfs ON tfs.train_id = t.id JOIN station fs ON fs.id = tfs.station_id JOIN train_station tts ON tts.train_id = t.id JOIN station ts ON ts.id = tts.station_id WHERE fs.station_name = #{from} AND ts.station_name = #{to} AND tfs.station_order < tts.station_order AND t.status = 1
AND t.train_type = #{trainType}
ORDER BY tfs.departure_time
